export default function collect({ previous, response }) {
  const s = previous ?? { items: [], offset: "", seen: [], started: false };
  if (!s.started) return { state: { ...s, started: true }, more: true, offset: "", items: [] };
  if (
    !response ||
    typeof response !== "object" ||
    !Array.isArray(response.items) ||
    !response.pagination ||
    typeof response.pagination.nextPage !== "boolean"
  )
    throw Error("Invalid Squarespace collection page");
  const items = [...s.items, ...response.items],
    next = response.pagination.nextPage;
  if (!next) return { state: { ...s, items }, more: false, offset: "", items };
  const value = response.pagination.nextPageOffset;
  if (!Number.isSafeInteger(value) || value < 0 || s.seen.includes(value))
    throw Error("Invalid or repeated Squarespace offset");
  return {
    state: { ...s, items, offset: String(value), seen: [...s.seen, value] },
    more: true,
    offset: String(value),
    items: [],
  };
}

