export default function next({ tasks, previous, confirmation, sheetName }) {
  const s = previous ?? { index: 0, waiting: false, pageId: null };
  if (s.waiting) {
    if (confirmation !== 9) throw Error("Sheet update not fully confirmed");
    s.index++;
    s.waiting = false;
  }
  s.pageId = null;
  if (s.index >= tasks.length)
    return { state: s, more: false, item: {}, range: "'unused'!A1:ZZZ1" };
  const item = tasks[s.index];
  if (!item || !Number.isSafeInteger(item.index) || item.index < 2)
    throw Error("Invalid sheet task");
  const q = "'" + sheetName.replace(/'/g, "''") + "'";
  return {
    state: { ...s, waiting: true, pageId: item.id },
    more: true,
    item,
    range: q + "!A" + item.index + ":ZZZ" + item.index,
  };
}

